class Solution {
public:
    int longestLine(vector<vector<int>>& mat) {
        int m = mat.size(), n = mat[0].size();
        if (m == 0 || n == 0) return 0;
        vector<vector<vector<int>>> dp(m, vector<vector<int>>(n, vector<int>(4, 0)));
        int maxLine = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (mat[r][c] == 1) {
                    dp[r][c][0] = (c > 0 ? dp[r][c - 1][0] : 0) + 1;
                    dp[r][c][1] = (r > 0 ? dp[r - 1][c][1] : 0) + 1;
                    dp[r][c][2] = (r > 0 && c > 0 ? dp[r - 1][c - 1][2] : 0) + 1;
                    dp[r][c][3] = (r > 0 && c + 1 < n ? dp[r - 1][c + 1][3] : 0) + 1;
                    maxLine = max({maxLine, dp[r][c][0], dp[r][c][1], dp[r][c][2], dp[r][c][3]});
                }
            }
        }
        return maxLine;
    }
};

class Solution {
    public int longestLine(int[][] mat) {
        int m = mat.length, n = mat[0].length;
        if (m == 0 || n == 0) return 0;
        int[][][] dp = new int[m][n][4];
        int maxLine = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (mat[r][c] == 1) {
                    dp[r][c][0] = (c > 0 ? dp[r][c - 1][0] : 0) + 1;
                    dp[r][c][1] = (r > 0 ? dp[r - 1][c][1] : 0) + 1;
                    dp[r][c][2] = (r > 0 && c > 0 ? dp[r - 1][c - 1][2] : 0) + 1;
                    dp[r][c][3] = (r > 0 && c + 1 < n ? dp[r - 1][c + 1][3] : 0) + 1;
                    for (int k = 0; k < 4; k++) {
                        maxLine = Math.max(maxLine, dp[r][c][k]);
                    }
                }
            }
        }
        return maxLine;
    }
}

