var longestLine = function(mat) {
    const m = mat.length, n = mat[0].length;
    if (m === 0 || n === 0) return 0;
    const dp = Array.from({ length: m }, () => Array.from({ length: n }, () => [0, 0, 0, 0]));
    let maxLine = 0;
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (mat[r][c] === 1) {
                dp[r][c][0] = (c > 0 ? dp[r][c - 1][0] : 0) + 1;
                dp[r][c][1] = (r > 0 ? dp[r - 1][c][1] : 0) + 1;
                dp[r][c][2] = (r > 0 && c > 0 ? dp[r - 1][c - 1][2] : 0) + 1;
                dp[r][c][3] = (r > 0 && c + 1 < n ? dp[r - 1][c + 1][3] : 0) + 1;
                maxLine = Math.max(maxLine, dp[r][c][0], dp[r][c][1], dp[r][c][2], dp[r][c][3]);
            }
        }
    }
    return maxLine;
};
